(() => {
  let boardState=null;
  let operatingState=null;

  function durationFromProject(){const values=(assetsCache||[]).map(a=>Number(a?.metadata?.duration_seconds||0)).filter(x=>x>0);return values.length?Math.max(...values):0;}
  function v2(){return Number(operatingState?.director_brain_version||0)>=2;}
  function overallMode(){return v2()?String(operatingState?.production_mode||''):'';}
  function rowHtml(index,start='',end=''){
    const mode=overallMode();
    return `<fieldset class="story-row" data-story-row>
      <legend>Shot ${index}</legend>
      <div class="toolbar"><label>Start seconds<input data-story-start type="number" min="0" step="0.001" value="${start}"></label><label>End seconds<input data-story-end type="number" min="0" step="0.001" value="${end}"></label><button type="button" class="soft" data-story-remove>Remove</button></div>
      ${v2()?`<div class="story-mode-block"><label>Production behavior<select data-story-mode ${mode==='hybrid'?'':'disabled'}><option value="cinematic">Cinematic</option><option value="living_scene">Living scene</option></select></label><p class="micro">${mode==='hybrid'?'Choose behavior for this shot.':`Project mode: ${mode.replaceAll('_',' ')}`}</p></div>`:''}
      <label>Story / visual action<textarea data-story-action rows="2" placeholder="What happens or visibly changes in this shot"></textarea></label>
      <label>Visual media<textarea data-story-visual rows="2" placeholder="Image, footage, generated media, composite, framing"></textarea></label>
      <label>Animation / camera behavior<textarea data-story-motion rows="2" placeholder="Internal motion, depth, camera, materials, particles"></textarea></label>
      ${v2()?`<div data-living-fields><label>Motion regions<input data-story-motion-regions placeholder="rain; hair; smoke; reflected light"></label><label>Protected regions<input data-story-protected-regions placeholder="face; hands; logo; horizon"></label><p class="micro">Required for living-scene shots. Separate regions with semicolons.</p></div>`:''}
      <label>Music cue<input data-story-music placeholder="Beat, section, energy change, instrument cue"></label>
      <label>Lyric cue (only when active)<input data-story-lyric placeholder="Exact lyric/meaning cue, or leave blank"></label>
      <label>Transition<input data-story-transition placeholder="Cut, dissolve, light handoff, match move"></label>
    </fieldset>`;
  }
  function effectiveMode(row){const overall=overallMode();if(overall==='hybrid')return row.querySelector('[data-story-mode]')?.value||'cinematic';return overall;}
  function updateLivingFields(row){const host=row.querySelector('[data-living-fields]');if(host)host.hidden=effectiveMode(row)!=='living_scene';}
  function renumber(){[...document.querySelectorAll('[data-story-row]')].forEach((r,i)=>r.querySelector('legend').textContent=`Shot ${i+1}`);}
  function bindRows(){document.querySelectorAll('[data-story-remove]').forEach(b=>b.onclick=()=>{b.closest('[data-story-row]').remove();renumber();});document.querySelectorAll('[data-story-mode]').forEach(s=>{s.onchange=()=>updateLivingFields(s.closest('[data-story-row]'));updateLivingFields(s.closest('[data-story-row]'));});}
  function addRow(start='',end=''){const host=$('storyboardRows'),n=host.querySelectorAll('[data-story-row]').length+1;host.insertAdjacentHTML('beforeend',rowHtml(n,start,end));const row=host.lastElementChild;if(overallMode()&&overallMode()!=='hybrid'&&row.querySelector('[data-story-mode]'))row.querySelector('[data-story-mode]').value=overallMode();bindRows();}
  function seedRows(){ $('storyboardRows').innerHTML='';const duration=durationFromProject(),count=4;for(let i=0;i<count;i++){const start=duration?Number((duration*i/count).toFixed(3)):'',end=duration?Number((duration*(i+1)/count).toFixed(3)):'';addRow(start,end);} }
  function splitRegions(v){return String(v||'').split(';').map(x=>x.trim()).filter(Boolean);}
  function entries(){return [...document.querySelectorAll('[data-story-row]')].map((r,i)=>{const mode=effectiveMode(r);const out={shot_id:`shot-${String(i+1).padStart(3,'0')}`,start_seconds:Number(r.querySelector('[data-story-start]').value),end_seconds:Number(r.querySelector('[data-story-end]').value),story_action:r.querySelector('[data-story-action]').value.trim(),visual_media:r.querySelector('[data-story-visual]').value.trim(),animation_behavior:r.querySelector('[data-story-motion]').value.trim(),music_cues:[r.querySelector('[data-story-music]').value.trim()].filter(Boolean),lyric_cue:r.querySelector('[data-story-lyric]').value.trim(),transition:r.querySelector('[data-story-transition]').value.trim()};if(v2()){out.production_mode=mode;if(mode==='living_scene'){out.motion_regions=splitRegions(r.querySelector('[data-story-motion-regions]')?.value);out.protected_regions=splitRegions(r.querySelector('[data-story-protected-regions]')?.value);}}return out;});}
  function validate(rows){if(!rows.length)return'Add at least one storyboard shot.';for(let i=0;i<rows.length;i++){const r=rows[i];if(!Number.isFinite(r.start_seconds)||!Number.isFinite(r.end_seconds)||r.end_seconds<=r.start_seconds)return`Shot ${i+1} needs a valid start and end time.`;if(i===0&&Math.abs(r.start_seconds)>0.001)return'The storyboard must begin at 0 seconds.';if(i>0&&Math.abs(r.start_seconds-rows[i-1].end_seconds)>0.002)return`Shot ${i+1} must start exactly where shot ${i} ends.`;if(!r.story_action||!r.visual_media||!r.animation_behavior||!r.music_cues.length||!r.transition)return`Complete action, visual, motion, music cue, and transition for shot ${i+1}.`;if(v2()&&r.production_mode==='living_scene'&&(!r.motion_regions?.length||!r.protected_regions?.length))return`Shot ${i+1} is a living scene and needs motion regions plus protected regions.`;}const duration=durationFromProject();if(duration&&Math.abs(rows.at(-1).end_seconds-duration)>0.05)return`The final shot must end at the project duration (${duration.toFixed(3)}s).`;return null;}
  async function saveBoard(){const rows=entries(),problem=validate(rows);if(problem){$('productionStatus').textContent=problem;return false;}const fps=Number($('storyboardFps').value||30);try{boardState=await toolCall('storyboard.set',{project_id:projectId(),entries:rows,target_fps:fps,summary:$('storyboardSummary').value.trim(),authority:'studio_current_user'});$('productionStatus').textContent=`Storyboard draft saved · ${boardState.entry_count||rows.length} shots · full frame coverage.`;await refreshBoardStatus();return true;}catch(e){$('productionStatus').textContent=e.message;return false;}}
  async function lockBoard(){if(!await saveBoard())return;const instruction=$('storyboardLockInstruction').value.trim();if(!instruction){$('productionStatus').textContent='Record the instruction approving this storyboard before locking it.';return;}$('lockStoryboard').disabled=true;try{boardState=await toolCall('storyboard.lock',{project_id:projectId(),recorded_instruction:instruction});$('productionStatus').textContent='Storyboard and production script locked. Continue production to run canonical guards.';$('storyboardDialog').close();await refreshBoardStatus();await loadProductionStatus();}catch(e){$('productionStatus').textContent=e.message;}finally{$('lockStoryboard').disabled=false;}}
  async function openBoard(){try{[boardState,operatingState]=await Promise.all([toolCall('storyboard.status',{project_id:projectId()}),toolCall('operating.status',{project_id:projectId()}).catch(()=>null)]);}catch(e){$('productionStatus').textContent=e.message;return;}$('storyboardFps').value=boardState.target_fps||30;seedRows();$('storyboardDialog').showModal();}
  async function refreshBoardStatus(){const button=$('storyboardEditor'),status=$('storyboardStatus');if(!button||!status)return;const stage=productionState?.stage,relevant=['APPROACH_ESTABLISHED','STORYBOARD_LOCKED'].includes(stage);button.hidden=stage!=='APPROACH_ESTABLISHED';if(!relevant){status.hidden=true;boardState=null;return;}try{boardState=await toolCall('storyboard.status',{project_id:projectId()});status.hidden=false;status.textContent=boardState.storyboard_exists?`Storyboard: ${boardState.entry_count} shots · ${boardState.total_frames||'—'} frames · ${boardState.production_mode||'legacy'} · ${boardState.storyboard_locked&&boardState.script_locked?'locked; awaiting stage verification':'draft'}.`:'Storyboard: not authored yet.';}catch(e){status.hidden=false;status.textContent=e.message;}}

  $('storyboardEditor')?.addEventListener('click',openBoard);$('addStoryboardRow')?.addEventListener('click',()=>addRow());$('saveStoryboard')?.addEventListener('click',saveBoard);$('lockStoryboard')?.addEventListener('click',lockBoard);setInterval(refreshBoardStatus,2500);setTimeout(refreshBoardStatus,500);
})();